import{ClientEventTypes as e}from"../schema/ClientEventTypes";export class SynthesizedSamplesDetector{mediaPlayout;name="synthesized-samples-detector";disabled=!1;constructor(e){this.mediaPlayout=e}get peerConnection(){return this.mediaPlayout.getPeerConnection()}get config(){return this.peerConnection.parent.config.syntheticSamplesDetector}update(){if(this.disabled)return;if(this.mediaPlayout.deltaSynthesizedSamplesDuration<=this.config.minSynthesizedSamplesDuration)return;const t=this.peerConnection.parent;t.emit("synthesized-audio",{mediaPlayoutMonitor:this.mediaPlayout,clientMonitor:t}),this.config.createEvent&&t.addEvent({type:e.EXCESSIVE_SYNTHESIZED_AUDIO,payload:{deltaSynthesizedSamplesDuration:this.mediaPlayout.deltaSynthesizedSamplesDuration}})}}